-- Intros under the category titles for the new catalogue tree (cat-texts): rewrites the intros the tree
-- made inaccurate (only while they are still the 2026-10-16 text) and fills every active category that
-- has none (only if still empty, so BO edits stay). Keyed by link_rewrite = the tree.yml node key.

UPDATE ps_category_lang cl
JOIN ps_lang l ON l.id_lang = cl.id_lang AND l.iso_code = 'sk'
JOIN ps_category c ON c.id_category = cl.id_category AND c.active = 1
JOIN (
  SELECT 'bundy-a-vesty' AS node, '<p>Softshellové bundy, vetrovky a vesty do premenlivého počasia. Chránia pred vetrom a hodia sa na turistiku, do práce aj ako firemné oblečenie s logom.</p>' AS old_text, '<p>Bundy, softshellové bundy, vetrovky, vesty aj pláštenky do premenlivého počasia. Hodia sa na turistiku, do práce vonku aj ako firemné oblečenie s logom.</p>' AS new_text
  UNION ALL SELECT 'bundy', '<p>Ľahké vetrovky aj zateplené bundy na prechodné obdobie a chladnejšie dni. Pánske a dámske modely v rôznych farbách.</p>', '<p>Zateplené, viacvrstvové a hybridné bundy na prechodné obdobie aj chladné dni. Pánske, dámske aj unisex modely v rôznych farbách.</p>'
  UNION ALL SELECT 'nohavice-a-sortky', '<p>Tepláky, legíny a šortky na šport, voľný čas aj pohodlie doma. Pánske aj dámske strihy.</p>', '<p>Nohavice, tepláky, legíny a šortky na prácu, šport aj voľný čas. Pánske, dámske aj detské strihy.</p>'
  UNION ALL SELECT 'teplaky', '<p>Pohodlné tepláky a legíny na šport, cvičenie aj voľný čas.</p>', '<p>Pohodlné tepláky na šport, cvičenie aj voľný čas. Pánske, dámske aj detské modely.</p>'
  UNION ALL SELECT 'pracovne-bundy', '<p>Odolné pracovné bundy a vesty, ktoré chránia pred chladom a vetrom pri práci vonku.</p>', '<p>Odolné pracovné bundy a parky, ktoré chránia pred chladom a vetrom pri práci vonku, vrátane reflexných modelov.</p>'
  UNION ALL SELECT 'obuv', '<p>Pracovná a bezpečnostná obuv od značiek Bata Industrials, Puma a Albatros. Poltopánky, členková obuv aj sandále do dielne, skladu či na stavbu.</p>', '<p>Pracovná a bezpečnostná obuv od značiek Bata Industrials, Puma a Albatros – poltopánky, členková obuv a sandále. K tomu plážové žabky a šľapky na leto aj s potlačou.</p>'
  UNION ALL SELECT 'doplnky-a-prislusenstvo', '<p>Čiapky, šiltovky, šatky, tašky, uteráky a pracovné doplnky. Drobnosti, ktoré dotvoria firemnú kolekciu alebo poslúžia ako reklamný darček s logom.</p>', '<p>Pokrývky hlavy, tašky a batohy, písacie potreby, hrnčeky, technológie a stovky ďalších reklamných predmetov. Väčšinu z nich môžete doplniť potlačou alebo gravírovaním loga.</p>'
  UNION ALL SELECT 'siltovky', '<p>Šiltovky a klobúky, ktoré chránia pred slnkom a s logom poslúžia ako reklamný predmet.</p>', '<p>Šiltovky a šilty proti slnku pre dospelých aj deti. S logom poslúžia ako obľúbený reklamný predmet.</p>'
) t ON t.node COLLATE utf8mb4_bin = cl.link_rewrite COLLATE utf8mb4_bin
SET cl.description = t.new_text
WHERE cl.description COLLATE utf8mb4_bin = t.old_text COLLATE utf8mb4_bin;

UPDATE ps_category_lang cl
JOIN ps_lang l ON l.id_lang = cl.id_lang AND l.iso_code = 'sk'
JOIN ps_category c ON c.id_category = cl.id_category AND c.active = 1
JOIN (
  SELECT 'vetrovky' AS node, '<p>Ľahké vetrovky, ktoré chránia pred vetrom a dajú sa zbaliť do malého priestoru.</p>' AS new_text
  UNION ALL SELECT 'plastenky', '<p>Pláštenky a pončá do dažďa – pre dospelých aj deti, aj vo vreckovom prevedení na kľúče.</p>'
  UNION ALL SELECT 'nohavice', '<p>Pánske a dámske nohavice strihu chinos na každý deň aj do práce.</p>'
  UNION ALL SELECT 'leginy', '<p>Dámske legíny na šport, cvičenie aj voľný čas.</p>'
  UNION ALL SELECT 'saty', '<p>Dámske šaty z príjemných materiálov na každý deň.</p>'
  UNION ALL SELECT 'sukne', '<p>Dámske sukne na každý deň aj do práce.</p>'
  UNION ALL SELECT 'pracovne-vesty', '<p>Pracovné vesty s praktickými vreckami, ktoré nechajú voľnosť rukám pri práci.</p>'
  UNION ALL SELECT 'sportove-oblecenie', '<p>Športové tričká a kraťasy pre dospelých aj deti, vhodné na tímové a firemné športové akcie.</p>'
  UNION ALL SELECT 'slapky', '<p>Plážové žabky a šľapky na leto, k vode aj do wellness. Niektoré modely vyrobíme s vašou potlačou.</p>'
  UNION ALL SELECT 'pokryvky-hlavy', '<p>Čiapky, šiltovky a klobúky na každé počasie. S logom sú praktickým reklamným predmetom.</p>'
  UNION ALL SELECT 'klobuky', '<p>Slamené, rybárske a party klobúky na leto, festivaly aj firemné akcie.</p>'
  UNION ALL SELECT 'satky-saly-rukavice', '<p>Šatky, šály, nákrčníky, rukavice a kravaty na šport, voľný čas aj do kancelárie.</p>'
  UNION ALL SELECT 'saly', '<p>Viacúčelové šatky, nákrčníky a šály, ktoré zahrejú krk aj hlavu.</p>'
  UNION ALL SELECT 'rukavice', '<p>Rukavice na chladné dni, aj s povrchom na ovládanie dotykovej obrazovky.</p>'
  UNION ALL SELECT 'kravaty', '<p>Kravaty v jednofarebnom aj vzorovanom prevedení do kancelárie aj na firemné podujatia.</p>'
  UNION ALL SELECT 'batohy', '<p>Batohy a ruksaky do školy, do práce, na výlety aj na notebook.</p>'
  UNION ALL SELECT 'tasky-cez-rameno', '<p>Tašky cez rameno a vodeodolné lodné vaky na cesty aj voľný čas.</p>'
  UNION ALL SELECT 'nakupne-tasky', '<p>Nákupné tašky z bavlny, juty, netkanej textílie aj recyklovaných materiálov. S potlačou sú obľúbeným reklamným darčekom.</p>'
  UNION ALL SELECT 'papierove-tasky', '<p>Papierové tašky a darčekové tašky v rôznych veľkostiach – do obchodu, na veľtrh aj na balenie darčekov.</p>'
  UNION ALL SELECT 'darcekove-tasky', '<p>Bavlnené darčekové tašky a vrecká so šnúrkou na balenie darčekov aj výrobkov.</p>'
  UNION ALL SELECT 'plazove-tasky', '<p>Plážové tašky, ktoré poslúžia aj ako priestranné nákupné tašky.</p>'
  UNION ALL SELECT 'chladiace-tasky', '<p>Chladiace tašky a batohy, ktoré udržia jedlo a nápoje chladné na výlete, pikniku aj v práci.</p>'
  UNION ALL SELECT 'sportove-tasky', '<p>Športové a cestovné tašky, tašky na topánky a vaky na tréning aj na cesty.</p>'
